{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Attenuate input embeddings by (1 + log(1 + training frequency))^(-0.1). Counts come only from each category's training interactions and persist in its single checkpoint. The generated predictor imports the same model class and restores these counts automatically. Embeddings, GRU, readout, loss and optimizer remain unchanged.",
      "edits": [
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        },
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"item_train_counts\", torch.zeros(itemnum + 1, dtype=torch.float32))\n        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        scale = (1.0 + torch.log1p(self.item_train_counts[seq])).pow(-0.1)\n        return self.item_emb(seq) * scale.unsqueeze(-1)\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.input_embeddings(seq))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.input_embeddings(seq))"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    item_train_counts = np.zeros(itemnum + 1, dtype=np.float32)\n    for history in user_train.values():\n        np.add.at(item_train_counts, np.asarray(history, dtype=np.int64), 1.0)\n    item_train_counts[0] = 0.0\n    with torch.no_grad():\n        model.item_train_counts.copy_(torch.from_numpy(item_train_counts).to(device))\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Add fixed training-frequency attenuation to GRU inputs, with counts restored from each category checkpoint during prediction. Preserve all four routes and existing training settings."
}
